async function runToTSearch(config, projectInfo, requirement, initialThought, strategy = "bfs", maxDepth = 6, beamWidth = 5, branchingFactor = 7, memoPlugin) {
  const engine = new TreeOfThoughtsEngine(config, projectInfo, requirement, { memoPlugin });
  const tree = await engine.initializeTree(initialThought, strategy, maxDepth, beamWidth, branchingFactor);
  let bestNode;
  switch (strategy) {
    case "bfs":
      bestNode = await engine.bfsSearch(tree);
      break;
    case "dfs":
      bestNode = await engine.dfsSearch(tree);
      break;
    case "beam":
      bestNode = await engine.beamSearch(tree);
      break;
    default:
      throw new Error(`Unknown search strategy: ${strategy}`);
  }
  if (bestNode) {
    let current = bestNode;
    while (current && current.parentId) {
      current.state = "selected" /* SELECTED */;
      const parent = tree.nodes.get(current.parentId);
      if (parent) {
        current = parent;
      } else {
        break;
      }
    }
    tree.root.state = "selected" /* SELECTED */;
    tree.metadata.solutionPath = getSolutionPath(tree, bestNode);
  }
  return { tree, bestNode };
}
function getSolutionPath(tree, leaf) {
  const path4 = [];
  let current = leaf;
  while (current) {
    path4.unshift(current);
    current = current.parentId ? tree.nodes.get(current.parentId) : null;
  }
  return path4;
}
