function filterThinkingProcess(response) {
  const lines = response.split(`
`);
  const filteredLines = [];
  let inThinkingProcess = false;
  let hasSeenThinkingProcess = false;
  for (const line of lines) {
    const numberedStepMatch = line.match(/^\s*\d+\.\s+/);
    const thinkingKeywords = ["\u8BC6\u522B", "\u5206\u6790", "\u786E\u5B9A", "\u8D77\u8349", "\u9009\u62E9", "\u683C\u5F0F\u5316", "\u6700\u7EC8\u8F93\u51FA"];
    const hasThinkingKeyword = thinkingKeywords.some((keyword) => line.includes(keyword));
    if (numberedStepMatch || hasThinkingKeyword && line.includes("**")) {
      inThinkingProcess = true;
      hasSeenThinkingProcess = true;
      continue;
    }
    if (inThinkingProcess) {
      if (line.trim() === "" || !numberedStepMatch && !hasThinkingKeyword) {
        inThinkingProcess = false;
        continue;
      }
      continue;
    }
    filteredLines.push(line);
  }
  if (filteredLines.length === 0 && hasSeenThinkingProcess) {
    const allLines = response.split(`
`).filter((l) => l.trim());
    if (allLines.length > 0) {
      const lastLines = allLines.slice(-3);
      return lastLines.join(`
`);
    }
  }
  const filtered = filteredLines.join(`
`).trim();
  if (!filtered) {
    return response.trim();
  }
  return filtered;
}
async function callAIWithFunctionCalling(config, projectInfo, userRequirement, history, registry, signal, skillManager) {
  const endpoint = config.endpoint || `${(config.baseUrl || "https://api.openai.com").replace(/\/+$/, "")}/v1/chat/completions`;
  const systemPrompt = `You are KODE, an AI assistant with tools.

Complete tasks efficiently using available tools.
Be concise. Keep responses under 3 sentences when possible.`;
  const fileTreeSnippet = JSON.stringify(projectInfo, null, 2);
  const userPrompt = `Project: ${fileTreeSnippet}

Task: ${userRequirement}

Use tools to complete this task.`;
  const toolDefinitions = buildToolDefinitions(registry, skillManager);
  const requestBody = {
    model: config.model,
    temperature: 0,
    messages: [
      { role: "system", content: systemPrompt },
      ...history,
      { role: "user", content: userPrompt }
    ],
    tools: toolDefinitions
  };
  const startTime = Date.now();
  const apiCallStart = Date.now();
  try {
    const fetchResponse = await fetch5(endpoint, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${config.apiKey}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify(requestBody),
      signal
    });
    const apiCallDuration = Date.now() - apiCallStart;
    console.log(source_default.gray(`\u23F1\uFE0F  [API] \u5355\u6B21\u8C03\u7528\u8017\u65F6: ${apiCallDuration}ms
`));
    if (!fetchResponse.ok) {
      const err = await fetchResponse.text();
      throw new Error(`OpenAI API error: ${fetchResponse.status} - ${err}`);
    }
    const data2 = await fetchResponse.json();
    const duration = Date.now() - startTime;
    const usage = data2.usage ? {
      prompt_tokens: data2.usage.prompt_tokens,
      completion_tokens: data2.usage.completion_tokens,
      total_tokens: data2.usage.total_tokens
    } : undefined;
    const message = data2.choices?.[0]?.message;
    if (!message) {
      return {
        type: "error",
        message: "No message in API response",
        duration,
        usage
      };
    }
    if (message.tool_calls && message.tool_calls.length > 0) {
      return {
        type: "tool_calls",
        toolCalls: message.tool_calls,
        done: false,
        duration,
        usage
      };
    }
    if (message.content) {
      const done = checkIfTaskDone(message.content);
      return {
        type: "text",
        content: message.content,
        done,
        duration,
        usage
      };
    }
    return {
      type: "error",
      message: "API response missing both tool_calls and content",
      duration,
      usage
    };
  } catch (error) {
    const duration = Date.now() - startTime;
    if (error.name === "AbortError") {
      return {
        type: "error",
        message: "Request was cancelled",
        duration
      };
    }
    console.error(source_default.red("\u274C Function Calling API error:"), error.message);
    return {
      type: "error",
      message: error.message || "Unknown error occurred",
      duration
    };
  }
}
function checkIfTaskDone(content) {
  const doneKeywords = [
    "done",
    "completed",
    "finished",
    "\u603B\u7ED3",
    "\u5B8C\u6210",
    "complete",
    "successfully"
  ];
  const lowerContent = content.toLowerCase();
  return doneKeywords.some((keyword) => lowerContent.includes(keyword));
}
