// src/memory/skill-generator.ts
import { mkdir as mkdir5, writeFile as writeFile4 } from "fs/promises";
import { join as join22 } from "path";

class SkillGenerator {
  projectRoot;
  options;
  constructor(projectRoot, options) {
    this.projectRoot = projectRoot;
    this.options = options;
  }
  async generate(suggestions) {
    const startTime = Date.now();
    console.log(`[Generator] Generating ${suggestions.length} skill files...`);
    const filePaths = [];
    for (const suggestion of suggestions) {
      try {
        const filePath = await this.generateOne(suggestion);
        filePaths.push(filePath);
        console.log(`[Generator] \u2713 Generated: ${suggestion.name}`);
      } catch (error48) {
        console.error(`[Generator] \u2717 Failed to generate ${suggestion.name}: ${error48.message}`);
      }
    }
    const duration3 = Date.now() - startTime;
    console.log(`[Generator] \u2713 Generated ${filePaths.length}/${suggestions.length} skills in ${duration3}ms`);
    return {
      skillsGenerated: filePaths.length,
      filePaths,
      duration: duration3
    };
  }
  async generateOne(suggestion) {
    const dirName = this.sanitizeDirName(suggestion.name);
    const targetDir = join22(this.options.targetDir, dirName);
    await mkdir5(targetDir, { recursive: true });
    const content = this.formatSkillFile(suggestion);
    const filePath = join22(targetDir, "SKILL.md");
    await writeFile4(filePath, content, "utf-8");
    if (this.options.includeMetadata) {
      const metadataPath = join22(targetDir, "metadata.json");
      await writeFile4(metadataPath, JSON.stringify(suggestion, null, 2), "utf-8");
    }
    return filePath;
  }
  formatSkillFile(suggestion) {
    const yaml = this.formatYaml(suggestion);
    const markdown = this.formatMarkdown(suggestion);
    return `${yaml}
${markdown}`;
  }
  formatYaml(suggestion) {
    const lines = ["---"];
    lines.push(`name: ${suggestion.name}`);
    lines.push(`description: ${suggestion.description}`);
    lines.push(`type: ${suggestion.type}`);
    lines.push(`complexity: ${suggestion.complexity}`);
    if (suggestion.tags.length > 0) {
      lines.push(`tags: [${suggestion.tags.map((t) => `"${t}"`).join(", ")}]`);
    }
    lines.push(`confidence: ${suggestion.confidence}`);
    if (suggestion.id) {
      lines.push(`generatedAt: "${suggestion.generatedAt?.toISOString()}"`);
    }
    if (suggestion.evidence.length > 0) {
      lines.push(`evidenceCount: ${suggestion.evidence.length}`);
    }
    if (this.options.saveAsDraft) {
      lines.push(`status: draft`);
      lines.push(`autoGenerated: true`);
    }
    lines.push("---");
    return lines.join(`
`);
  }
  formatMarkdown(suggestion) {
    const sections = [];
    sections.push(`# ${suggestion.name}
`);
    sections.push(`## \u6982\u8FF0
`);
    sections.push(`${suggestion.description}
`);
    if (suggestion.whenToUse.length > 0) {
      sections.push(`## \u4F7F\u7528\u573A\u666F
`);
      suggestion.whenToUse.forEach((scenario) => {
        sections.push(`- ${scenario}
`);
      });
      sections.push("");
    }
    sections.push(`## \u6838\u5FC3\u77E5\u8BC6
`);
    sections.push(`${suggestion.coreKnowledge}
`);
    if (suggestion.evidence.length > 0) {
      sections.push(`## \u652F\u6301\u8BC1\u636E
`);
      suggestion.evidence.forEach((evidence) => {
        sections.push(`### ${this.formatEvidenceSource(evidence.source)}
`);
        sections.push(`${evidence.description}
`);
        sections.push(`**\u51FA\u73B0\u6B21\u6570**: ${evidence.count || "N/A"}
`);
        if (evidence.examples.length > 0) {
          sections.push(`**\u793A\u4F8B**:
`);
          evidence.examples.forEach((example) => {
            sections.push(`- \`${example}\`
`);
          });
        }
        if (evidence.lastSeen) {
          sections.push(`**\u6700\u540E\u51FA\u73B0**: ${new Date(evidence.lastSeen).toLocaleDateString()}
`);
        }
        sections.push("");
      });
    }
    if (suggestion.examples.length > 0) {
      sections.push(`## \u793A\u4F8B
`);
      suggestion.examples.forEach((example, index2) => {
        sections.push(`### \u793A\u4F8B ${index2 + 1}: ${example.scenario}
`);
        sections.push(`${example.solution}
`);
        if (example.code) {
          sections.push(`**\u4EE3\u7801**:
`);
          sections.push("```");
          sections.push(example.code);
          sections.push("```\n");
        }
      });
    }
    if (this.options.includeMetadata && this.options.saveAsDraft) {
      sections.push(`---
`);
      sections.push(`## \u5143\u6570\u636E
`);
      sections.push(`
<!-- Generated by Newma Precipitation System -->
`);
      sections.push(`<!-- Confidence: ${(suggestion.confidence * 100).toFixed(1)}% -->
`);
      sections.push(`<!-- Generated: ${suggestion.generatedAt?.toISOString()} -->
`);
    }
    return sections.join(`
`);
  }
  formatEvidenceSource(source) {
    const names = {
      errors: "\u9519\u8BEF\u8BB0\u5F55",
      history: "\u6267\u884C\u5386\u53F2",
      preferences: "\u7528\u6237\u504F\u597D",
      context: "\u9879\u76EE\u4E0A\u4E0B\u6587",
      reasoning: "\u63A8\u7406\u8FC7\u7A0B",
      decisions: "\u51B3\u7B56\u8BB0\u5F55",
      sessions: "\u4F1A\u8BDD\u5386\u53F2"
    };
    return names[source] || source;
  }
  sanitizeDirName(name) {
    return name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").substring(0, 50);
  }
  async loadSuggestionsFromTemp(tempFilePath) {
    const { readFile: readFile5 } = __require("fs/promises");
    const content = await readFile5(tempFilePath, "utf-8");
    return JSON.parse(content);
  }
  validateSkillFile(content) {
    const hasFrontmatter = content.startsWith("---");
    if (!hasFrontmatter)
      return false;
    const requiredFields = ["name:", "description:", "type:"];
    const hasRequiredFields = requiredFields.some((field) => content.includes(field));
    return hasRequiredFields;
  }
}

