class PrecipitationCoordinator {
  projectRoot;
  config;
  explorationConfig;
  scheduler;
  analyzer;
  generator;
  draftManager;
  newmaConfig;
  constructor(options, newmaConfig) {
    this.projectRoot = options.projectRoot;
    this.config = options.precipitationConfig || {};
    this.explorationConfig = options.explorationConfig;
    this.newmaConfig = newmaConfig;
    this.scheduler = new MemoryScheduler({
      config: this.config,
      explorationConfig: this.explorationConfig,
      runOnStart: false
    });
    this.analyzer = new ExperienceAnalyzer(this.projectRoot, this.buildAnalyzerOptions());
    this.generator = new SkillGenerator(this.projectRoot, this.buildGeneratorOptions());
    this.draftManager = new SkillDraftManager(this.projectRoot);
  }
  async start(precipitationCallback, explorationCallback) {
    console.log("[Precipitation] Starting precipitation system...");
    if (this.config.enabled === false) {
      console.log("[Precipitation] \u26A0 Precipitation system disabled");
      return;
    }
    if (this.config.initOnStart !== false) {
      await this.draftManager.initialize();
      await this.ensurePrecipitationDir();
    }
    this.scheduler.start(precipitationCallback || (async () => {
      await this.executePrecipitation();
    }), explorationCallback);
    console.log("[Precipitation] \u2713 Precipitation system started");
    this.logScheduleInfo();
  }
  async stop() {
    console.log("[Precipitation] Stopping precipitation system...");
    this.scheduler.stop();
    console.log("[Precipitation] \u2713 Precipitation system stopped");
  }
  async trigger() {
    console.log("[Precipitation] \uD83D\uDD39 Manually triggering precipitation...");
    return await this.executePrecipitation();
  }
  getStatus() {
    return {
      scheduler: this.scheduler.getStatus(),
      drafts: this.draftManager.getStats(),
      config: this.config
    };
  }
  async executePrecipitation() {
    const startTime = new Date;
    const logs = [];
    logs.push(`[${startTime.toISOString()}] Starting precipitation`);
    try {
      logs.push("[Step 1] Analyzing experiences...");
      const analysisResult = await this.analyzer.analyze(this.newmaConfig);
      logs.push(`\u2713 Analysis complete: ${analysisResult.suggestionsPassed} suggestions generated`);
      const suggestions = await this.loadSuggestions();
      logs.push(`\u2713 Loaded ${suggestions.length} suggestions from temp file`);
      let autoApproved = 0;
      let autoRejected = 0;
      if (this.config.autoApproveBelow || this.config.autoRejectAbove) {
        const autoResult = await this.autoApproveOrReject(suggestions);
        autoApproved = autoResult.approved;
        autoRejected = autoResult.rejected;
        logs.push(`\u2713 Auto-approved: ${autoApproved}, Auto-rejected: ${autoRejected}`);
      }
      logs.push("[Step 2] Generating skill files...");
      const generationResult = await this.generator.generate(suggestions);
      logs.push(`\u2713 Generated ${generationResult.skillsGenerated} skill files`);
      if (this.config.draftRetentionDays) {
        const cleaned = await this.draftManager.cleanupOldDrafts();
        logs.push(`\u2713 Cleaned up ${cleaned} old drafts`);
      }
      const endTime = new Date;
      logs.push(`[${endTime.toISOString()}] Precipitation complete`);
      return {
        success: true,
        startTime,
        endTime,
        suggestionsGenerated: analysisResult.suggestionsGenerated,
        draftsSaved: generationResult.skillsGenerated,
        autoApproved,
        autoRejected,
        logs
      };
    } catch (error48) {
      const endTime = new Date;
      logs.push(`[${endTime.toISOString()}] Precipitation failed: ${error48.message}`);
      return {
        success: false,
        startTime,
        endTime,
        suggestionsGenerated: 0,
        draftsSaved: 0,
        autoApproved: 0,
        autoRejected: 0,
        error: error48.message,
        logs
      };
    }
  }
  async autoApproveOrReject(suggestions) {
    let approved = 0;
    let rejected = 0;
    for (const suggestion of suggestions) {
      const id = this.extractDraftId(suggestion);
      if (this.config.autoApproveBelow && suggestion.confidence >= this.config.autoApproveBelow) {
        try {
          await this.draftManager.approve(id, "Auto-approved by system");
          approved++;
        } catch (error48) {
          console.warn(`Failed to auto-approve ${id}`);
        }
      }
      if (this.config.autoRejectAbove && suggestion.confidence < this.config.autoRejectAbove) {
        try {
          await this.draftManager.reject(id, "Auto-rejected by system");
          rejected++;
        } catch (error48) {
          console.warn(`Failed to auto-reject ${id}`);
        }
      }
    }
    return { approved, rejected };
  }
  async loadSuggestions() {
    const precipitationDir = join24(this.projectRoot, ".memo", "precipitation");
    const { readdir: readdir5, readFile: readFile6 } = __require("fs/promises");
    const files = await readdir5(precipitationDir);
    const tempFiles = files.filter((f) => f.startsWith("suggestions-") && f.endsWith(".json"));
    if (tempFiles.length === 0) {
      return [];
    }
    const latestFile = tempFiles.sort().reverse()[0];
    const content = await readFile6(join24(precipitationDir, latestFile), "utf-8");
    return JSON.parse(content);
  }
  extractDraftId(suggestion) {
    return suggestion.id || `skill-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
  buildAnalyzerOptions() {
    return {
      confidenceThreshold: this.config.confidenceThreshold || 0.6,
      maxSkills: this.config.maxDailySkills || 5,
      analysisDays: this.config.analysisDays || 7,
      weights: {
        errors: 0.4,
        history: 0.3,
        preferences: 0.2,
        others: 0.1
      }
    };
  }
  buildGeneratorOptions() {
    return {
      saveAsDraft: true,
      targetDir: join24(this.projectRoot, ".kode", "skills", "drafts"),
      includeMetadata: true
    };
  }
  async ensurePrecipitationDir() {
    const dir = join24(this.projectRoot, ".memo", "precipitation");
    await mkdir7(dir, { recursive: true });
  }
  logScheduleInfo() {
    const schedule2 = this.config.schedule || "0 2 * * *";
    const description = MemoryScheduler.describeCronExpression(schedule2);
    const nextRun = this.scheduler.getNextExecution();
    console.log(`[Precipitation] Schedule: ${description} (${schedule2})`);
    if (nextRun) {
      console.log(`[Precipitation] Next run: ${nextRun.toISOString()}`);
    }
  }
  getDraftManager() {
    return this.draftManager;
  }
  getScheduler() {
    return this.scheduler;
  }
}

