          console.log(source_default.gray(`Next run: ${status.scheduler.nextExecution ? status.scheduler.nextExecution.toLocaleString() : "N/A"}`));
          const precipJob = status.scheduler.jobs.find((j) => j.name === "precipitation");
          console.log(source_default.gray(`Last run: ${precipJob?.lastRun ? precipJob.lastRun.toLocaleString() : "Never"}`));
          console.log("");
