  determineExecutionMode() {
    const config3 = this.session.getConfig();
    const executionMode = config3.executionMode || "standard";
    const modeMap = {
      subagent: "sub-agent",
      "multi-agent": "multi-agent",
      "function-calling": "function-calling",
      fft: "fft",
      "state-machine": "state-machine",
      standard: "standard"
    };
    return modeMap[executionMode] || "standard";
  }
  async executeWithFunctionCalling(requirement, projectInfo) {
    if (!this.toolExecutor) {
      console.log(source_default.red(`\u274C Tool executor not available
`));
      return;
    }
    const config3 = this.session.getConfig();
    const registry2 = this.toolExecutor.getRegistry();
    const history = [];
    let iteration = 0;
    const MAX_ITERATIONS = 10;
    while (iteration < MAX_ITERATIONS) {
      iteration++;
      console.log(source_default.gray(`
[\u8FED\u4EE3 ${iteration}] \u8C03\u7528 AI...
`));
      this.currentAbortController = new AbortController;
      const iterStart = Date.now();
      try {
        const aiResp = await callAIWithFunctionCalling(config3, projectInfo, requirement, history, registry2, this.getAbortSignal());
        const iterDuration = Date.now() - iterStart;
        console.log(source_default.gray(`\u23F1\uFE0F  [Function Calling] \u8FED\u4EE3 ${iteration} \u8017\u65F6: ${iterDuration}ms
`));
        this.resetAbortController();
        if (aiResp.type === "tool_calls" && aiResp.toolCalls) {
          console.log(source_default.cyan(`\uD83D\uDD27 AI \u8C03\u7528\u4E86 ${aiResp.toolCalls.length} \u4E2A\u5DE5\u5177
`));
          history.push({
            role: "assistant",
            tool_calls: aiResp.toolCalls,
            content: null
          });
          const toolResults = await Promise.all(aiResp.toolCalls.map(async (call) => {
            const toolName = source_default.cyan(call.function.name);
            console.log(`  \u2699\uFE0F  [${toolName}] ${call.function.arguments}`);
            const args = JSON.parse(call.function.arguments);
            const result = await this.toolExecutor.executeToolCall({
              tool: call.function.name,
              parameters: args,
              id: call.id
            });
            if (result.success) {
              console.log(source_default.green(`  \u2705 [${toolName}] \u6210\u529F`));
              const output = result.output?.slice(0, 200) || "Done";
              if ((result.output?.length || 0) > 200) {
                console.log(source_default.gray(`  \uD83D\uDCC4 ${output}... (truncated)`));
              } else {
                console.log(source_default.gray(`  \uD83D\uDCC4 ${output}`));
              }
            } else {
              console.log(source_default.red(`  \u274C [${toolName}] \u5931\u8D25: ${result.error}`));
            }
            return {
              role: "tool",
              tool_call_id: call.id,
              content: JSON.stringify(result)
            };
          }));
          history.push(...toolResults);
          console.log(source_default.gray(`
\u2705 \u5DE5\u5177\u6267\u884C\u5B8C\u6210\uFF0C\u7EE7\u7EED...
`));
          continue;
        }
        if (aiResp.type === "text" || aiResp.type === "error") {
          console.log(source_default.gray(`
` + "\u2500".repeat(50)));
          console.log(source_default.cyan(`\uD83D\uDCDD AI \u54CD\u5E94\uFF1A
`));
          if (aiResp.type === "error") {
            console.log(source_default.yellow(aiResp.message || "Unknown error"));
          } else {
            console.log(aiResp.content || "No content");
          }
          console.log(source_default.gray(`
` + "\u2500".repeat(50)) + `
`);
          if (aiResp.content) {
            history.push({
              role: "assistant",
              content: aiResp.content
            });
          }
          if (aiResp.done) {
            console.log(source_default.green(`\u2705 \u4EFB\u52A1\u5B8C\u6210\uFF01
`));
          }
          break;
        }
      } catch (error48) {
        this.resetAbortController();
        if (error48.name === "AbortError" || error48.message?.includes("abort")) {
          console.log(source_default.yellow(`
\u26A0\uFE0F  \u6267\u884C\u88AB\u53D6\u6D88.
`));
          return;
        }
        console.error(source_default.red("\u274C Function Calling error:"), error48.message);
        console.error(source_default.gray(error48.stack));
        break;
      }
    }
    if (iteration >= MAX_ITERATIONS) {
      console.log(source_default.yellow(`\u26A0\uFE0F  \u8FBE\u5230\u6700\u5927\u8FED\u4EE3\u6B21\u6570 (${MAX_ITERATIONS})\uFF0C\u7EC8\u6B62\u5FAA\u73AF
`));
    }
    console.log(source_default.gray(`\u23F1\uFE0F  [Function Calling] \u603B\u8FED\u4EE3\u6B21\u6570: ${iteration}
`));
  }
