  describeAction(action) {
    switch (action.type) {
      case "create":
        return `Create ${action.path}`;
      case "modify":
        return `Modify ${action.path}`;
      case "delete":
        return `Delete ${action.path}`;
      case "run":
        return `Run "${action.command}"`;
      case "verify":
        return `Verify "${action.command}"`;
      default:
        return `Unknown action: ${JSON.stringify(action)}`;
    }
  }
