  isValidTaskRequirement(requirement) {
    if (requirement.length < 3) {
      return false;
    }
    const lowerReq = requirement.toLowerCase().trim();
    const greetings = [
      "hi",
      "hello",
      "hey",
      "yo",
      "\u4F60\u597D",
      "\u60A8\u597D",
      "\u55E8",
      "\u65E9\u4E0A\u597D",
      "\u4E0B\u5348\u597D",
      "\u665A\u4E0A\u597D",
      "greetings"
    ];
    if (greetings.some((g) => lowerReq === g)) {
      return false;
    }
    return true;
  }
