// src/loop/frontends/cli-frontend.ts
init_source();
init_frontend2();
import readline4 from "readline";

class CliFrontend {
  type = "cli";
  rl;
  config;
  interruptHandler;
  isRunningFlag = false;
  history = [];
  constructor(config3 = {}) {
    this.config = {
      prompt: config3.prompt || "[newma] \u276F ",
      colors: config3.colors !== false,
      debug: config3.debug || false,
      input: config3.input || process.stdin,
      output: config3.output || process.stdout,
      historySize: config3.historySize || 100
    };
    this.rl = readline4.createInterface({
      input: this.config.input,
      output: this.config.output,
      prompt: this.config.prompt,
      historySize: this.config.historySize
    });
    this.setupCompatibility();
  }
  setupCompatibility() {}
  async readInput(prompt2) {
    return new Promise((resolve5) => {
      const actualPrompt = prompt2 || this.config.prompt;
      this.rl.question(actualPrompt, (answer) => {
        this.history.push(answer.trim());
        if (this.history.length > this.config.historySize) {
          this.history.shift();
        }
        resolve5(answer.trim());
      });
    });
  }
  writeOutput(content, style = "default" /* DEFAULT */) {
    if (!this.config.colors) {
      console.log(content);
      return;
    }
    switch (style) {
      case "success" /* SUCCESS */:
        console.log(source_default.green(content));
        break;
      case "error" /* ERROR */:
        console.log(source_default.red(content));
        break;
      case "warning" /* WARNING */:
        console.log(source_default.yellow(content));
        break;
      case "info" /* INFO */:
        console.log(source_default.cyan(content));
        break;
      case "debug" /* DEBUG */:
        if (this.config.debug) {
          console.log(source_default.gray(content));
        }
        break;
      case "code" /* CODE */:
        console.log(source_default.gray(content));
        break;
      case "default" /* DEFAULT */:
      default:
        console.log(content);
        break;
    }
  }
  writeError(content) {
    this.writeOutput(content, "error" /* ERROR */);
  }
  clearScreen() {
    console.clear();
  }
  showStatus(status) {
    const modeSymbols = {
      chat: "\uD83D\uDCAC",
      plan: "\uD83D\uDCCB",
      execute: "\u2699\uFE0F",
      verify: "\u2705",
      loop: "\uD83D\uDD04"
    };
    const symbol2 = modeSymbols[status.mode] || "\uD83D\uDCCC";
    const modeText = status.mode.toUpperCase();
    if (status.isRunning) {
      let statusText = `${symbol2} ${modeText} Mode`;
      if (status.iteration !== undefined && status.maxIterations) {
        statusText += ` (${status.iteration}/${status.maxIterations})`;
      }
      this.writeOutput(statusText, "info" /* INFO */);
    } else {
      this.writeOutput(`${symbol2} ${modeText} Mode (Stopped)`, "warning" /* WARNING */);
    }
  }
  showProgress(progress) {
    let progressText = `\u23F3 ${progress.message}`;
    if (progress.percentage !== undefined) {
      progressText += ` (${progress.percentage}%)`;
    } else if (progress.current !== undefined && progress.total !== undefined) {
      progressText += ` (${progress.current}/${progress.total})`;
    }
    this.writeOutput(progressText, "info" /* INFO */);
  }
  async start() {
    if (this.isRunningFlag) {
      return;
    }
    this.isRunningFlag = true;
    this.rl.on("SIGINT", () => {
      if (this.interruptHandler) {
        this.interruptHandler();
      } else {
        this.writeOutput(`
\u6309 Ctrl+C \u518D\u6B21\u9000\u51FA`, "warning" /* WARNING */);
      }
    });
  }
  async stop() {
    if (!this.isRunningFlag) {
      return;
    }
    this.isRunningFlag = false;
    this.rl.close();
  }
  isRunning() {
    return this.isRunningFlag;
  }
  setInterruptHandler(handler) {
    this.interruptHandler = handler;
  }
  setPrompt(prompt2) {
    this.config.prompt = prompt2;
    this.rl.setPrompt(prompt2);
  }
  getHistory() {
    return [...this.history];
  }
  clearHistory() {
    this.history = [];
  }
}

