import { EventEmitter as EventEmitter12 } from "events";

class MCPServer extends EventEmitter12 {
  handlers;
  serverInfo;
  initialized = false;
  serverCapabilities;
  constructor(handlers, serverInfo = {
    name: "newma-cli",
    version: "1.0.0"
  }) {
    super();
    this.handlers = handlers;
    this.serverInfo = serverInfo;
    this.serverCapabilities = {
      ...handlers.listTools && { tools: {} },
      ...handlers.listResources && { resources: {} },
      ...handlers.listPrompts && { prompts: {} }
    };
  }
  async handleRequest(request) {
    const { method, params, id } = request;
    try {
      if (method === "initialize") {
        return await this.handleInitialize(params, id);
      }
      if (!this.initialized) {
        return {
          jsonrpc: "2.0",
          id,
          error: {
            code: -32002,
            message: "Server not initialized"
          }
        };
      }
      switch (method) {
        case "tools/list":
          return await this.handleListTools(id);
        case "tools/call":
          return await this.handleCallTool(params, id);
        case "resources/list":
          return await this.handleListResources(id);
        case "resources/read":
          return await this.handleReadResource(params, id);
        case "prompts/list":
          return await this.handleListPrompts(id);
        case "prompts/get":
          return await this.handleGetPrompt(params, id);
        default:
          return {
            jsonrpc: "2.0",
            id,
            error: {
              code: -32601,
              message: `Method not found: ${method}`
            }
          };
      }
    } catch (error48) {
      return {
        jsonrpc: "2.0",
        id,
        error: {
          code: -32603,
          message: `Internal error: ${error48}`,
          data: error48
        }
      };
    }
  }
  async handleInitialize(params, id) {
    const response = {
      protocolVersion: "2024-11-05",
      capabilities: this.serverCapabilities,
      serverInfo: this.serverInfo
    };
    this.initialized = true;
    this.emit("initialized");
    return {
      jsonrpc: "2.0",
      id,
      result: response
    };
  }
  async handleListTools(id) {
    if (!this.handlers.listTools) {
      return {
        jsonrpc: "2.0",
        id,
        error: {
          code: -32601,
          message: "Tools not supported"
        }
      };
    }
    const tools = await this.handlers.listTools();
    return {
      jsonrpc: "2.0",
      id,
      result: { tools }
    };
  }
  async handleCallTool(params, id) {
    if (!this.handlers.callTool) {
      return {
        jsonrpc: "2.0",
        id,
        error: {
          code: -32601,
          message: "Tool calling not supported"
        }
      };
    }
    const context = { requestId: id };
    const result = await this.handlers.callTool(params, context);
    return {
      jsonrpc: "2.0",
      id,
      result
    };
  }
  async handleListResources(id) {
    if (!this.handlers.listResources) {
      return {
        jsonrpc: "2.0",
        id,
        error: {
          code: -32601,
          message: "Resources not supported"
        }
      };
    }
    const resources = await this.handlers.listResources();
    return {
      jsonrpc: "2.0",
      id,
      result: { resources }
    };
  }
  async handleReadResource(params, id) {
    if (!this.handlers.readResource) {
      return {
        jsonrpc: "2.0",
        id,
        error: {
          code: -32601,
          message: "Resource reading not supported"
        }
      };
    }
    const content = await this.handlers.readResource(params.uri, { requestId: id });
    return {
      jsonrpc: "2.0",
      id,
      result: {
        contents: [
          {
            uri: params.uri,
            mimeType: "text/plain",
            text: content
          }
        ]
      }
    };
  }
  async handleListPrompts(id) {
    if (!this.handlers.listPrompts) {
      return {
        jsonrpc: "2.0",
        id,
        error: {
          code: -32601,
          message: "Prompts not supported"
        }
      };
    }
    const prompts = await this.handlers.listPrompts();
    return {
      jsonrpc: "2.0",
      id,
      result: { prompts }
    };
  }
  async handleGetPrompt(params, id) {
    if (!this.handlers.getPrompt) {
      return {
        jsonrpc: "2.0",
        id,
        error: {
          code: -32601,
          message: "Prompts not supported"
        }
      };
    }
    const content = await this.handlers.getPrompt(params.name, params.arguments || {}, { requestId: id });
    return {
      jsonrpc: "2.0",
      id,
      result: {
        messages: [
          {
            role: "user",
            content: {
              type: "text",
              text: content
            }
          }
        ]
      }
    };
  }
}
function createMCPServerFromRegistry(registry2) {
  const handlers = {
    async listTools() {
      const tools = registry2.list();
      return tools.map((tool) => ({
        name: tool.name,
        description: tool.description,
        inputSchema: {
          type: "object",
          properties: tool.parameters || {},
          required: (tool.parameters || []).filter((p) => p.required).map((p) => p.name)
        }
      }));
    },
    async callTool(request, context) {
      try {
        const call = {
          id: String(context.requestId),
          tool: request.name,
          parameters: request.arguments || {}
        };
        const result = await registry2.executeToolCall(call, {
          root: process.cwd(),
          history: null,
          permissions: new Set,
          config: {}
        });
        if (result.success) {
          return {
            content: [
              {
                type: "text",
                text: result.output || ""
              }
            ]
          };
        } else {
          return {
            content: [
              {
                type: "text",
                text: result.error || "Unknown error"
              }
            ],
            isError: true
          };
        }
      } catch (error48) {
        return {
          content: [
            {
              type: "text",
              text: `Error: ${error48}`
            }
          ],
          isError: true
        };
      }
    }
  };
  return new MCPServer(handlers);
}
async function runStdioServer(server) {
  let buffer = "";
  process.stdin.setEncoding("utf-8");
  process.stdin.on("data", (data2) => {
    buffer += data2;
    const lines = buffer.split(`
`);
    buffer = lines.pop() || "";
    for (const line of lines) {
      if (!line.trim())
        continue;
      try {
        const request = JSON.parse(line);
        server.handleRequest(request).then((response) => {
          process.stdout.write(JSON.stringify(response) + `
`);
        });
      } catch (error48) {
        const errorResponse = {
          jsonrpc: "2.0",
          id: -1,
          error: {
            code: -32700,
            message: `Parse error: ${error48}`
          }
        };
        process.stdout.write(JSON.stringify(errorResponse) + `
`);
      }
    }
  });
  process.on("SIGINT", () => {
    process.exit(0);
  });
  process.on("SIGTERM", () => {
    process.exit(0);
  });
}

