async function runApiMode(config3, projectRoot, input, options = {}) {
  const { mode = "chat", silent = true } = options;
  const projectInfo = await scanDirectory(projectRoot);
  let response;
  if (mode === "chat") {
    response = await chatAI(config3, input, undefined, undefined);
  } else {
    const aiMode = mode === "do" ? "think" : mode;
    const result = await callAI(config3, projectInfo, input, aiMode, [], undefined, undefined, undefined, projectRoot);
    response = result.content || "";
  }
  return response;
}
async function readStdin() {
  return new Promise((resolve6, reject) => {
    let data2 = "";
    process.stdin.setEncoding("utf-8");
    process.stdin.on("data", (chunk) => {
      data2 += chunk;
    });
    process.stdin.on("end", () => {
      resolve6(data2.trim());
    });
    process.stdin.on("error", (error48) => {
      reject(error48);
    });
    setTimeout(() => {
      reject(new Error("stdin read timeout"));
    }, 5000);
  });
}

